use std :: process :: Command ; use std :: fs ; use std :: path :: Path ; use std :: time :: Instant ; fn print_zkperf_integration_summary (test_results : & [ZkperfIntegrationResult]) { let total_tests = test_results . len () ; let passed_tests = test_results . iter () . filter (| r | r . passed) . count () ; let failed_tests = total_tests - passed_tests ; let success_rate = (passed_tests as f64 / total_tests as f64) * 100.0 ; let total_duration : u64 = test_results . iter () . map (| r | r . duration_ms) . sum () ; let avg_duration = total_duration as f64 / total_tests as f64 ; let total_files : usize = test_results . iter () . map (| r | r . output_files . len ()) . sum () ; let successful_files : usize = test_results . iter () . filter (| r | r . passed) . map (| r | r . output_files . len ()) . sum () ; println ! ("\n🔗 ZKperf Integration Test Summary") ; println ! ("==================================") ; println ! ("📊 Total ZKperf Integration Tests: {}" , total_tests) ; println ! ("✅ Passed: {}" , passed_tests) ; println ! ("❌ Failed: {}" , failed_tests) ; println ! ("📈 Success Rate: {:.1}%" , success_rate) ; println ! ("⏱️  Total Time: {}ms" , total_duration) ; println ! ("📊 Average Time: {:.1}ms" , avg_duration) ; println ! ("📁 Total Files Generated: {}" , total_files) ; println ! ("✅ Successful Files: {}" , successful_files) ; if failed_tests == 0 { println ! ("🎉 All ZKperf integration tests passed! The Repository Mathematical Atlas has excellent ZKperf integration.") ; } else { println ! ("⚠️  {} ZKperf integration tests failed. Please review the ZKperf integration report for details." , failed_tests) ; } println ! ("\n📄 Detailed ZKperf integration report available in: ./zkperf_integration_report.md") ; }